// Compatibility is limited to the exact profile generated by #780/#782.
// No expiry renewal, identity rebinding, grant or pause mutation is permitted.
export function upgradeGeneratedPublicationProfile(profile) {
  if (
    profile.textOnly !== true ||
    profile.url !== "https://www.facebook.com/" ||
    profile.resolvePostLinks !== true ||
    profile.receiptUrl !== profile.identityHref ||
    profile.selectors?.attachmentName !== "[data-ftrade-unreviewed-attachment]" ||
    profile.selectors?.composer !== '[role="dialog"]:has([role="textbox"])' ||
    profile.selectors?.textbox !== '[role="textbox"][contenteditable="true"]' ||
    profile.selectors?.fileInput !== 'input[type="file"]' ||
    !profile.selectors?.composerIdentity ||
    !profile.selectors?.receiptIdentity
  )
    return profile;
  return {
    ...profile,
    textOnly: false,
    imagePreview: "blob-sha256",
    videoReceipt: { mode: "captioned_post" },
    receiptScroll: 900,
    audienceText: "Public",
    adapterRevision: "generated-media-v1",
  };
}
